#include "../LanSettingsDraft.hpp"
#include "../LocaleNative.hpp"
#import <AppKit/AppKit.h>
#include <thread>
@interface CliptiqLanAction : NSObject <NSWindowDelegate> { @public std::function<void(NSInteger)> callback; std::function<void()> closed; }
- (void)clicked:(id)sender;
@end
@implementation CliptiqLanAction
- (void)clicked:(id)sender {if(callback)callback([sender tag]);}
- (void)windowWillClose:(NSNotification*)note {(void)note;if(closed)closed();}
@end
namespace cliptiq {
namespace {NSString* ls(const std::string&s){return [[NSString alloc] initWithBytes:s.data() length:s.size() encoding:NSUTF8StringEncoding]?:@"";}}
struct NativeLanSettings::State {
 std::thread::id owner=std::this_thread::get_id();NSWindow* window=nil;NSTextField* message=nil;NSStackView* stack=nil;CliptiqLanAction* target=nil;
 bool embedded=false;lan::Config saved;
 LanSettingsDraft draft;Save save;std::function<Result<std::string>()> generate;std::function<Result<void>(std::string)> copy;
 struct Input{LanSettingsDraft::Field field;NSControl* widget;};std::vector<Input> inputs;std::map<NSInteger,std::pair<int,std::string>> actions;
 ~State(){if(target){target->callback={};target->closed={};}[window close];}
 void status(std::string s){message.stringValue=ls(s);}
 Result<void> collect(){[stack.window makeFirstResponder:nil];std::map<std::string,std::string> values;for(auto& i:inputs)values[i.field.key]=i.field.check?([(NSButton*)i.widget state]==NSControlStateValueOn?"1":"0"):std::string([(NSTextField*)i.widget stringValue].UTF8String);return draft.collect(values);}
 NSButton* button(NSString* title,int kind,std::string peer={}){auto b=[NSButton buttonWithTitle:loc(title) target:target action:@selector(clicked:)];b.tag=actions.size()+1;actions[b.tag]={kind,std::move(peer)};return b;}
 void build(){for(NSView* v in [stack.arrangedSubviews copy]){[stack removeArrangedSubview:v];[v removeFromSuperview];}inputs.clear();actions.clear();
 auto info=[NSTextField wrappingLabelWithString:loc(@"Changes take effect only after Save. No peers means LAN is off.")];[stack addArrangedSubview:info];
 for(auto& f:draft.fields()){auto row=[NSStackView new];row.orientation=NSUserInterfaceLayoutOrientationHorizontal;row.spacing=16;auto label=[NSTextField wrappingLabelWithString:ls(f.label)];[label.widthAnchor constraintEqualToConstant:330].active=YES;[row addArrangedSubview:label];NSControl* w=nil;if(f.check){auto b=[NSButton checkboxWithTitle:@"" target:nil action:nil];b.state=f.value=="1"?NSControlStateValueOn:NSControlStateValueOff;w=b;}else{NSTextField* e=f.secret?[NSSecureTextField new]:[NSTextField new];e.stringValue=ls(f.value);[e.widthAnchor constraintEqualToConstant:330].active=YES;w=e;}[row addArrangedSubview:w];[stack addArrangedSubview:row];inputs.push_back({f,w});if(f.secret){auto peer=f.key.substr(0,f.key.size()-4);auto buttons=[NSStackView new];buttons.orientation=NSUserInterfaceLayoutOrientationHorizontal;buttons.spacing=12;[buttons addArrangedSubview:button(@"Generate key",1,peer)];[buttons addArrangedSubview:button(@"Copy key",2,peer)];[buttons addArrangedSubview:button(@"Remove peer",3,peer)];[stack addArrangedSubview:buttons];}}
 auto buttons=[NSStackView new];buttons.orientation=NSUserInterfaceLayoutOrientationHorizontal;buttons.spacing=16;auto add=button(@"Add peer",4);add.enabled=draft.config.peers.size()<16;[buttons addArrangedSubview:add];[buttons addArrangedSubview:button(@"Save",5)];[buttons addArrangedSubview:button(@"Cancel",6)];[stack addArrangedSubview:buttons];message=[NSTextField wrappingLabelWithString:loc(@"Ready. Pair keys are stored securely after Save.")];[stack addArrangedSubview:message];}
 void action(NSInteger tag){auto it=actions.find(tag);if(it==actions.end())return;int kind=it->second.first;auto peer=it->second.second;if(kind==6){draft.keys.clear();if(embedded){draft.config=saved;build();}else [window orderOut:nil];return;}auto r=collect();if(!r){status(r.error().message);return;}if(kind==1){auto k=generate();if(!k){status(k.error().message);return;}draft.keys[peer]=k.value();build();}if(kind==2){auto k=draft.keys.find(peer);if(k==draft.keys.end()){status(tr("Enter or generate a key to copy. Saved keys are not displayed."));return;}auto c=copy(k->second);status(c?tr("Key copied. Keep it private."):c.error().message);}if(kind==3){draft.remove(peer);build();}if(kind==4){draft.add();build();}if(kind==5){auto s=save(draft.config,draft.keys);if(!s){status(s.error().message);return;}draft.keys.clear();saved=draft.config;if(embedded)build();else [window orderOut:nil];}}
};
NativeLanSettings::NativeLanSettings():state_(std::make_shared<State>()){}NativeLanSettings::~NativeLanSettings()=default;
Result<void> NativeLanSettings::show(lan::Config config,Save save,std::function<Result<std::string>()> generate,std::function<Result<void>(std::string)> copy,void* parent){auto s=state_;if(s->owner!=std::this_thread::get_id()||!NSThread.isMainThread)return Error{ErrorCode::InvalidArgument,"LAN settings require main thread"};if(!save||!generate||!copy)return Error{ErrorCode::InvalidArgument,"LAN settings callbacks required"};if(s->target){s->target->callback={};s->target->closed={};}[s->window close];s->window=nil;s->embedded=parent!=nullptr;s->saved=config;s->draft={std::move(config),{}};s->save=std::move(save);s->generate=std::move(generate);s->copy=std::move(copy);if(!parent){s->window=[[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,760,680) styleMask:NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskResizable backing:NSBackingStoreBuffered defer:NO];s->window.releasedWhenClosed=NO;s->window.title=loc(@"Advanced LAN settings");s->window.minSize=NSMakeSize(740,400);auto scroll=[[NSScrollView alloc] initWithFrame:s->window.contentView.bounds];scroll.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;scroll.hasVerticalScroller=YES;s->stack=[NSStackView new];s->stack.orientation=NSUserInterfaceLayoutOrientationVertical;s->stack.alignment=NSLayoutAttributeLeading;s->stack.spacing=12;s->stack.edgeInsets=NSEdgeInsetsMake(16,16,16,16);scroll.documentView=s->stack;s->stack.translatesAutoresizingMaskIntoConstraints=NO;[s->stack.leadingAnchor constraintEqualToAnchor:scroll.contentView.leadingAnchor].active=YES;[s->stack.topAnchor constraintEqualToAnchor:scroll.contentView.topAnchor].active=YES;[s->stack.widthAnchor constraintEqualToAnchor:scroll.contentView.widthAnchor].active=YES;[s->window.contentView addSubview:scroll];}else{s->stack=(__bridge NSStackView*)parent;}s->target=[CliptiqLanAction new];std::weak_ptr<State> weak=s;s->target->callback=[weak](NSInteger tag){if(auto s=weak.lock())s->action(tag);};s->target->closed=[weak]{if(auto s=weak.lock())s->draft.keys.clear();};s->window.delegate=s->target;s->build();if(!parent){[s->window center];[s->window makeKeyAndOrderFront:nil];}return {};}
Result<void> NativeLanSettings::process_events(){if(state_->owner!=std::this_thread::get_id()||!NSThread.isMainThread)return Error{ErrorCode::InvalidArgument,"LAN settings require main thread"};return {};}
void NativeLanSettings::status(std::string s){state_->status(std::move(s));}
}
